<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Entrar na corrida</title><style>body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}main{max-width:520px;margin:12vh auto;padding:28px}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:24px}h1{font-size:48px;letter-spacing:-.06em;line-height:.95}label{font-weight:800;display:block;margin-bottom:8px}input{font:inherit;padding:13px;width:100%;box-sizing:border-box;border:2px solid #dbe5e8;border-radius:12px}button{font:inherit;font-weight:900;border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;margin-top:16px;cursor:pointer}.muted{color:#637780;font-size:14px}</style></head><body><main><div class="panel"><div>🦆 PATO NA PISTA</div><h1>Entre na corrida</h1><p class="muted">Sala {{ $code }} · digite seu nome para participar.</p><label for="name">Seu nome</label><input id="name" placeholder="Ex.: Camila Souza" autofocus><button id="join">Entrar na corrida</button><p id="msg" class="muted"></p></div></main><script>document.getElementById('join').onclick=async()=>{const name=document.getElementById('name').value.trim(),msg=document.getElementById('msg');if(!name){msg.textContent='Digite seu nome.';return}const r=await fetch('/api/races/{{ $code }}/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});msg.textContent=r.ok?'Inscrição confirmada! Você já está na corrida.':'Sala não encontrada.'}</script></body></html>
